        title: '结论——谁该买',
        content:
          '**如果你想要一台便宜、低功耗的 Home Assistant 主机，并看重可更换、最高 32 GB 的内存插槽，就买 GMKtec G3 Plus。** 约 $180–200，它是进入本地优先智能家居的扎实入门之选。不要指望它是快速的本地助手——单通道 DDR4 的 Intel N150 只能处理小型模型。\n\n**G3 Plus 的不同之处：可升级内存。** 大多数预算级 N150 主机都是板载焊接内存。G3 Plus 改用可更换的 DDR4 SO-DIMM，最高支持 32 GB。这对 Home Assistant 服务器很重要，因为随着你的系统规模扩大，同一台机器之后可以承载更多附加组件、一个数据库，以及多一点本地 AI 上下文——无需购买新机器。\n\n**GMKtec G3 Plus 不是最好的本地 AI 电脑，而是少数几款最好的、也能运行本地 AI 的廉价 Home Assistant 电脑之一。** 如果你想要两个网口，Beelink EQ14 是更适合的主机；如果你想要真正的本地 AI 速度，请升级到 Ryzen 主机，例如 SER8。',
