          'Avaliamos mini PCs para uso local em casa inteligente considerando: compatibilidade com o Home Assistant, capacidade de expansão de RAM, expansão de armazenamento, rede, consumo em repouso, desempenho sustentado de CPU, capacidade de LLM local, características térmicas/de ruído, adequação para Docker/servidor e preço/custo-benefício.',
