      faqSection: {
        id: 'faq',
        title: 'Perguntas frequentes',
        faqs: [
          { q: 'O GMKtec G3 Plus é bom para Home Assistant?', a: 'Sim. Ele roda o Home Assistant e add-ons comuns (Zigbee2MQTT, Node-RED, AdGuard) com folga, em baixo consumo em repouso. Sua única porta 2.5GbE faz dele uma caixa de rede menos completa do que o Beelink EQ14, que tem LAN dupla.' },
          { q: 'O GMKtec G3 Plus consegue rodar o Ollama?', a: 'Sim. O Ollama instala e roda normalmente no G3 Plus; um modelo de 1B–4B responde bem, e modelos de 7–8B funcionam mas rodam devagar. Isso é estimado a partir do hardware verificado, não um benchmark fixo.' },
          { q: 'O GMKtec G3 Plus consegue rodar modelos Llama ou Qwen?', a: 'Sim, na faixa pequena. Um modelo Llama ou Qwen de 1B–4B em quantização 4-bit roda com conforto; uma variante de 7–8B é usável mas lenta por causa da largura de banda DDR4 de canal único e do N150 de quatro núcleos.' },
          { q: 'O G3 Plus consegue rodar um modelo de 7B?', a: 'Cabe e roda, mas devagar — espere que seja usável para tarefas não interativas (resumos, tarefas em lote) em vez de um chat ágil de ida e volta. Para um assistente 7B responsivo, uma caixa Ryzen como o Beelink SER8 é a escolha melhor.' },
          { q: 'Quanta RAM o G3 Plus suporta?', a: 'Até 32 GB por meio de um único SO-DIMM DDR4-3200. A GMKtec envia pré-configurado com 8 GB ou 16 GB — não existe SKU de fábrica com 32 GB, então chegar a 32 GB significa comprar e instalar o módulo você mesmo.' },
          { q: 'A RAM do G3 Plus é expansível ou soldada?', a: 'Expansível. O G3 Plus usa um único slot SO-DIMM DDR4 substituível, não memória soldada. Essa é uma vantagem real sobre caixas econômicas com RAM fixa — embora, em agosto de 2026, um SO-DIMM DDR4-3200 de 32 GB custe cerca de R$ 2.000–2.400 no Brasil por causa da escassez de memória no mercado, então cote o upgrade antes de considerá-lo barato.' },
          { q: 'Consigo instalar 32 GB de RAM eu mesmo?', a: 'Sim — é uma troca de SO-DIMM padrão. Compre um único módulo SO-DIMM DDR4-3200 de 32 GB (o slot é de canal único, então um módulo já basta) e substitua o que vem de fábrica.' },
          { q: 'O G3 Plus tem porta USB-C?', a: 'Não. Este modelo tem quatro portas USB-A e duas saídas HDMI, mas nenhuma porta USB-C. O Beelink EQ14, em comparação, tem uma porta USB-C (10 Gbps, só dados).' },
          { q: 'O G3 Plus tem LAN dupla?', a: 'Não — tem uma única porta 2.5GbE. O Beelink EQ14 tem duas portas 2.5GbE, o que o torna a melhor escolha se você quer que o mini PC também cumpra função de rede.' },
          { q: 'O G3 Plus consegue rodar o Frigate?', a: 'Consegue, mas a detecção só com CPU, sem NPU, limita a um número pequeno de câmeras em resolução/taxa de quadros modesta. É possível, não ideal — uma caixa Ryzen com iGPU mais forte lida melhor com o Frigate.' },
          { q: 'O GMKtec G3 Plus é melhor que o Beelink EQ14?', a: 'Nenhum dos dois é estritamente melhor — eles trocam vantagens diferentes. O G3 Plus vence no teto de RAM (32 GB vs 16 GB); o EQ14 vence em rede (2.5GbE dupla, mais uma porta USB-C). No Brasil, o G3 Plus também costuma sair mais barato. Escolha com base na troca que mais importa para sua configuração.' },
          { q: 'GMKtec G3 Plus vs Raspberry Pi 5 para Home Assistant?', a: 'O G3 Plus tem muito mais folga de RAM, compatibilidade x86 e espaço para adicionar um LLM local — o Pi 5 é mais barato e menor, mas bem mais limitado em RAM e CPU para qualquer coisa além do próprio Home Assistant.' },
          { q: 'O G3 Plus é bom para operação 24/7?', a: 'Sim. Com cerca de 6 W em repouso, é barato deixá-lo rodando continuamente, e análises independentes relatam térmica modesta sob carga leve sustentada. Não há dados de durabilidade de longo prazo, já que a PromptQuorum não rodou uma unidade continuamente.' },
          { q: 'Quanta energia o G3 Plus consome?', a: 'Cerca de 6 W em repouso e cerca de 21–26 W sob carga. Deixado majoritariamente em repouso por um ano inteiro, isso dá cerca de 52,6 kWh — um acréscimo pequeno e previsível na conta de luz, independente da tarifa local.' },
          { q: 'Vale a pena comprar o GMKtec G3 Plus em 2026?', a: 'Para o papel a que se propõe — um hub Home Assistant barato e de baixo consumo, com espaço para testar um modelo local pequeno — sim. Para quem realmente quer IA local rápida, não; esse orçamento rende mais em uma caixa Ryzen como o Beelink SER8.' },
          { q: 'Onde o GMKtec G3 Plus é fabricado, e isso afeta o preço?', a: 'É fabricado na China. Em 2026, medidas de importação dos EUA (tarifas da Seção 301, o fim da isenção de minimis abaixo de US$ 800) e a remoção pela UE do limite de € 150 para encomendas de baixo valor podem afetar o custo final; no Brasil, os impostos de importação pesam ainda mais sobre o preço pago pelo comprador. Verifique o preço atual do revendedor em vez de confiar em um número fixo.' },
        ],
      },
